#!/usr/bin/env python3
"""LOOP UNIVERSE: a standalone generated Python arcade of 9 MiB.

Run: python decorator_loop_universe_9MB.py
Choose an interactive game, or enter a numbered micro-experiment.
All experiments are actual executable functions, not padding or data blobs.
Each generated experiment contains decorators, if/else, while and for loops.
Only the Python standard library is needed.
"""
import functools
import math
import random
import time
from collections import Counter

REGISTRY = {}

def experiment(number, category):
    """Register and decorate an experiment for interactive execution."""
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(seed=42, steps=12):
            start = time.perf_counter()
            result = fn(seed, max(1, min(steps, 100)))
            return result, (time.perf_counter() - start) * 1000
        REGISTRY[number] = (category, wrapper)
        return wrapper
    return decorate

def bounded(low, high):
    """Decorator that limits inputs without hiding the original function."""
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(seed=42, steps=12):
            return fn(int(seed) % 1000000, max(low, min(high, int(steps))))
        return wrapper
    return decorate

def show_gallery():
    categories = Counter(cat for cat, _ in REGISTRY.values())
    print('\n' + '=' * 62)
    print(' LOOP UNIVERSE | DECORATORS + IF/ELSE + WHILE + FOR')
    print('=' * 62)
    print(f'{len(REGISTRY):,} executable micro-experiments available')
    for name, count in sorted(categories.items()):
        print(f'  {name:22s} : {count:,}')
    print('\nCommands: random | NUMBER | range A B | search WORD | help | quit')

def main():
    show_gallery()
    while True:
        try:
            command = input('\nuniverse> ').strip().lower()
        except (EOFError, KeyboardInterrupt):
            print('\nGoodbye, explorer!')
            return
        if command in ('quit', 'exit', 'q'):
            print('Goodbye, explorer!')
            return
        elif command in ('help', 'menu', ''):
            show_gallery()
        elif command == 'random':
            number = random.choice(tuple(REGISTRY))
            category, fn = REGISTRY[number]
            value, elapsed = fn(random.randrange(100000), 16)
            print(f'#{number} [{category}] => {value} ({elapsed:.3f} ms)')
        elif command.startswith('search '):
            term = command[7:].strip()
            matches = [(n, c) for n, (c, _) in REGISTRY.items() if term in c.lower()]
            print('Matches:', matches[:30], '...' if len(matches) > 30 else '')
        elif command.startswith('range '):
            try:
                _, a, b = command.split()
                a, b = int(a), int(b)
                for number in range(max(1, a), min(len(REGISTRY), b) + 1):
                    category, fn = REGISTRY[number]
                    value, _ = fn(number, 8)
                    print(f'#{number} [{category}] => {value}')
            except (ValueError, OverflowError):
                print('Use: range 1 10')
        else:
            try:
                number = int(command)
                category, fn = REGISTRY[number]
                raw_seed = input('seed [42]> ').strip()
                raw_steps = input('steps 1..100 [12]> ').strip()
                seed = int(raw_seed) if raw_seed else 42
                steps = int(raw_steps) if raw_steps else 12
                value, elapsed = fn(seed, steps)
                print(f'#{number} [{category}] => {value} ({elapsed:.3f} ms)')
            except (ValueError, KeyError):
                print('Unknown command or number. Enter help.')

@experiment(1, 'modular orbits')
@bounded(1, 100)
def experiment_00001(seed=42, steps=12):
    """Generated micro-experiment 1: modular orbits; parameters 294, 38, 19, 77."""
    cells = [(seed >> (j % 16) ^ (j * 294)) % 2 for j in range(38+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 19%2 else 1)
            else:
                new_cells.append(cells[j] if 77%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

@experiment(2, 'digital ecosystems')
@bounded(1, 100)
def experiment_00002(seed=42, steps=12):
    """Generated micro-experiment 2: digital ecosystems; parameters 765, 33, 42, 26."""
    candidate = max(2, (seed % 997) + 765)
    primes = []
    checked = 0
    while checked < steps:
        prime = candidate > 1
        for divisor in range(2, math.isqrt(candidate) + 1):
            if candidate % divisor == 0:
                prime = False
                break
            else:
                continue
        if prime:
            primes.append(candidate)
        else:
            candidate += 33%5
        candidate += 1
        checked += 1
    return {'primes': primes, 'count': len(primes), 'last_checked': candidate}

@experiment(3, 'prime wanderers')
@bounded(1, 100)
def experiment_00003(seed=42, steps=12):
    """Generated micro-experiment 3: prime wanderers; parameters 922, 32, 18, 23."""
    signal = [(seed + j*32 + 922) % 256 for j in range(18%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 32 < 16:
                transformed.append((value + 23 + j) % 256)
            else:
                transformed.append((value ^ 157) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

