def experiment_00252(seed=42, steps=12):
    """Generated micro-experiment 252: probability clocks; parameters 474, 32, 17, 73."""
    x = (seed + 474) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 32 < 16:
            x = (x * 17 + 73) % 100003
        else:
            x = (x + 474 * 32) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 32
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(253, 'modular orbits')
@bounded(1, 100)
def experiment_00253(seed=42, steps=12):
    """Generated micro-experiment 253: modular orbits; parameters 930, 13, 60, 56."""
    cells = [(seed >> (j % 16) ^ (j * 930)) % 2 for j in range(13+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 60%2 else 1)
            else:
                new_cells.append(cells[j] if 56%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

