def experiment_01345(seed=42, steps=12):
    """Generated micro-experiment 1345: modular orbits; parameters 243, 31, 17, 36."""
    cells = [(seed >> (j % 16) ^ (j * 243)) % 2 for j in range(31+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 17%2 else 1)
