    """Generated micro-experiment 1814: modular orbits; parameters 741, 10, 6, 55."""
    cells = [(seed >> (j % 16) ^ (j * 741)) % 2 for j in range(10+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 6%2 else 1)
            else:
                new_cells.append(cells[j] if 55%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

