def experiment_02250(seed=42, steps=12):
    """Generated micro-experiment 2250: prime wanderers; parameters 202, 40, 33, 9."""
    signal = [(seed + j*40 + 202) % 256 for j in range(33%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 40 < 20:
                transformed.append((value + 9 + j) % 256)
            else:
                transformed.append((value ^ 202) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

