def experiment_02757(seed=42, steps=12):
    """Generated micro-experiment 2757: sequence gardens; parameters 176, 4, 19, 28."""
    rng = random.Random(seed ^ 176)
    buckets = [0] * (4%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(19%13 + 3):
            toss = rng.randrange(1000)
            if toss % 28 < 14:
                bucket = (toss + j + 176) % len(buckets)
            else:
                bucket = (toss * 4 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

@experiment(2758, 'probability clocks')
@bounded(1, 100)
def experiment_02758(seed=42, steps=12):
    """Generated micro-experiment 2758: probability clocks; parameters 85, 19, 56, 87."""
    x = (seed + 85) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 19 < 9:
            x = (x * 56 + 87) % 100003
        else:
            x = (x + 85 * 19) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 19
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(2759, 'modular orbits')
@bounded(1, 100)
def experiment_02759(seed=42, steps=12):
    """Generated micro-experiment 2759: modular orbits; parameters 811, 34, 40, 9."""
    cells = [(seed >> (j % 16) ^ (j * 811)) % 2 for j in range(34+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 40%2 else 1)
            else:
                new_cells.append(cells[j] if 9%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

