def experiment_03192(seed=42, steps=12):
    """Generated micro-experiment 3192: probability clocks; parameters 484, 14, 34, 73."""
    x = (seed + 484) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 14 < 7:
            x = (x * 34 + 73) % 100003
        else:
            x = (x + 484 * 14) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 14
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(3193, 'modular orbits')
@bounded(1, 100)
def experiment_03193(seed=42, steps=12):
    """Generated micro-experiment 3193: modular orbits; parameters 337, 36, 7, 40."""
    cells = [(seed >> (j % 16) ^ (j * 337)) % 2 for j in range(36+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 7%2 else 1)
            else:
                new_cells.append(cells[j] if 40%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

