def experiment_03808(seed=42, steps=12):
    """Generated micro-experiment 3808: probability clocks; parameters 575, 31, 13, 86."""
    x = (seed + 575) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 31 < 15:
            x = (x * 13 + 86) % 100003
        else:
            x = (x + 575 * 31) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 31
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

