def experiment_03809(seed=42, steps=12):
    """Generated micro-experiment 3809: modular orbits; parameters 957, 14, 64, 58."""
    cells = [(seed >> (j % 16) ^ (j * 957)) % 2 for j in range(14+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 64%2 else 1)
