@experiment(4388, 'sequence gardens')
@bounded(1, 100)
def experiment_04388(seed=42, steps=12):
    """Generated micro-experiment 4388: sequence gardens; parameters 192, 15, 61, 64."""
    rng = random.Random(seed ^ 192)
    buckets = [0] * (15%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(61%13 + 3):
            toss = rng.randrange(1000)
            if toss % 64 < 32:
                bucket = (toss + j + 192) % len(buckets)
            else:
                bucket = (toss * 15 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

