@experiment(4390, 'modular orbits')
@bounded(1, 100)
def experiment_04390(seed=42, steps=12):
    """Generated micro-experiment 4390: modular orbits; parameters 846, 29, 62, 25."""
    cells = [(seed >> (j % 16) ^ (j * 846)) % 2 for j in range(29+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 62%2 else 1)
            else:
                new_cells.append(cells[j] if 25%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

