def experiment_05075(seed=42, steps=12):
    """Generated micro-experiment 5075: probability clocks; parameters 212, 18, 37, 9."""
    x = (seed + 212) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 18 < 9:
            x = (x * 37 + 9) % 100003
        else:
            x = (x + 212 * 18) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 18
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(5076, 'modular orbits')
@bounded(1, 100)
def experiment_05076(seed=42, steps=12):
    """Generated micro-experiment 5076: modular orbits; parameters 779, 26, 53, 24."""
    cells = [(seed >> (j % 16) ^ (j * 779)) % 2 for j in range(26+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 53%2 else 1)
            else:
                new_cells.append(cells[j] if 24%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

