def experiment_05401(seed=42, steps=12):
    """Generated micro-experiment 5401: signal machines; parameters 962, 2, 22, 8."""
    position = (seed + 962) % 500
    trail = []
    turn = 0
    while turn < steps:
        for direction in range(4):
            if (position + direction) % 2 == 0:
                position = (position + 22 * (direction+1)) % 500
            else:
                position = (position * 8 + direction) % 500
            trail.append(position)
        turn += 1
    return {'position': position, 'visited': len(set(trail)), 'trail': trail[-8:]}

