@experiment(5403, 'sequence gardens')
@bounded(1, 100)
def experiment_05403(seed=42, steps=12):
    """Generated micro-experiment 5403: sequence gardens; parameters 241, 35, 47, 36."""
    rng = random.Random(seed ^ 241)
    buckets = [0] * (35%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(47%13 + 3):
            toss = rng.randrange(1000)
            if toss % 36 < 18:
                bucket = (toss + j + 241) % len(buckets)
            else:
                bucket = (toss * 35 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

@experiment(5404, 'probability clocks')
@bounded(1, 100)
def experiment_05404(seed=42, steps=12):
    """Generated micro-experiment 5404: probability clocks; parameters 300, 11, 32, 74."""
    x = (seed + 300) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 11 < 5:
            x = (x * 32 + 74) % 100003
        else:
            x = (x + 300 * 11) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 11
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(5405, 'modular orbits')
@bounded(1, 100)
def experiment_05405(seed=42, steps=12):
    """Generated micro-experiment 5405: modular orbits; parameters 119, 5, 16, 38."""
    cells = [(seed >> (j % 16) ^ (j * 119)) % 2 for j in range(5+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 16%2 else 1)
            else:
                new_cells.append(cells[j] if 38%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

