def experiment_05582(seed=42, steps=12):
    """Generated micro-experiment 5582: prime wanderers; parameters 21, 10, 60, 12."""
    signal = [(seed + j*10 + 21) % 256 for j in range(60%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 10 < 5:
                transformed.append((value + 12 + j) % 256)
            else:
                transformed.append((value ^ 21) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

