    """Generated micro-experiment 5872: sequence gardens; parameters 317, 17, 6, 8."""
    rng = random.Random(seed ^ 317)
    buckets = [0] * (17%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(6%13 + 3):
            toss = rng.randrange(1000)
            if toss % 8 < 4:
                bucket = (toss + j + 317) % len(buckets)
            else:
                bucket = (toss * 17 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

