@experiment(5874, 'modular orbits')
@bounded(1, 100)
def experiment_05874(seed=42, steps=12):
    """Generated micro-experiment 5874: modular orbits; parameters 649, 6, 59, 86."""
    cells = [(seed >> (j % 16) ^ (j * 649)) % 2 for j in range(6+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 59%2 else 1)
