def experiment_06198(seed=42, steps=12):
    """Generated micro-experiment 6198: prime wanderers; parameters 696, 32, 61, 55."""
    signal = [(seed + j*32 + 696) % 256 for j in range(61%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 32 < 16:
                transformed.append((value + 55 + j) % 256)
            else:
                transformed.append((value ^ 186) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

