@bounded(1, 100)
def experiment_06203(seed=42, steps=12):
    """Generated micro-experiment 6203: modular orbits; parameters 468, 30, 58, 46."""
    cells = [(seed >> (j % 16) ^ (j * 468)) % 2 for j in range(30+8)]
    generation = 0
