    rng = random.Random(seed ^ 67)
    buckets = [0] * (38%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(8%13 + 3):
            toss = rng.randrange(1000)
            if toss % 68 < 34:
                bucket = (toss + j + 67) % len(buckets)
            else:
                bucket = (toss * 38 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

