def experiment_06923(seed=42, steps=12):
    """Generated micro-experiment 6923: probability clocks; parameters 406, 35, 53, 56."""
    x = (seed + 406) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 35 < 17:
            x = (x * 53 + 56) % 100003
        else:
            x = (x + 406 * 35) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 35
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

