    """Generated micro-experiment 7104: sequence gardens; parameters 667, 35, 57, 54."""
    rng = random.Random(seed ^ 667)
    buckets = [0] * (35%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(57%13 + 3):
            toss = rng.randrange(1000)
            if toss % 54 < 27:
                bucket = (toss + j + 667) % len(buckets)
            else:
                bucket = (toss * 35 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

