def experiment_07430(seed=42, steps=12):
    """Generated micro-experiment 7430: prime wanderers; parameters 633, 3, 55, 71."""
    signal = [(seed + j*3 + 633) % 256 for j in range(55%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 3 < 1:
                transformed.append((value + 71 + j) % 256)
            else:
                transformed.append((value ^ 123) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

