@experiment(7435, 'modular orbits')
@bounded(1, 100)
def experiment_07435(seed=42, steps=12):
    """Generated micro-experiment 7435: modular orbits; parameters 778, 11, 51, 32."""
    cells = [(seed >> (j % 16) ^ (j * 778)) % 2 for j in range(11+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 51%2 else 1)
