def experiment_08082(seed=42, steps=12):
    """Generated micro-experiment 8082: signal machines; parameters 253, 40, 42, 58."""
    position = (seed + 253) % 500
    trail = []
    turn = 0
    while turn < steps:
        for direction in range(4):
            if (position + direction) % 40 == 0:
                position = (position + 42 * (direction+1)) % 500
            else:
                position = (position * 58 + direction) % 500
            trail.append(position)
        turn += 1
    return {'position': position, 'visited': len(set(trail)), 'trail': trail[-8:]}

