@experiment(8084, 'sequence gardens')
@bounded(1, 100)
def experiment_08084(seed=42, steps=12):
    """Generated micro-experiment 8084: sequence gardens; parameters 132, 26, 11, 66."""
    rng = random.Random(seed ^ 132)
    buckets = [0] * (26%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(11%13 + 3):
            toss = rng.randrange(1000)
            if toss % 66 < 33:
                bucket = (toss + j + 132) % len(buckets)
            else:
                bucket = (toss * 26 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

@experiment(8085, 'probability clocks')
@bounded(1, 100)
def experiment_08085(seed=42, steps=12):
    """Generated micro-experiment 8085: probability clocks; parameters 745, 3, 63, 30."""
    x = (seed + 745) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 3 < 1:
            x = (x * 63 + 30) % 100003
        else:
            x = (x + 745 * 3) % 100003
        orbit.append(x)
        count += 1
    total = 0
