def experiment_08662(seed=42, steps=12):
    """Generated micro-experiment 8662: prime wanderers; parameters 650, 4, 4, 56."""
    signal = [(seed + j*4 + 650) % 256 for j in range(4%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 4 < 2:
                transformed.append((value + 56 + j) % 256)
            else:
                transformed.append((value ^ 140) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

