def experiment_09459(seed=42, steps=12):
    """Generated micro-experiment 9459: digital ecosystems; parameters 173, 18, 3, 46."""
    candidate = max(2, (seed % 997) + 173)
    primes = []
    checked = 0
    while checked < steps:
        prime = candidate > 1
        for divisor in range(2, math.isqrt(candidate) + 1):
            if candidate % divisor == 0:
                prime = False
                break
            else:
                continue
        if prime:
            primes.append(candidate)
        else:
            candidate += 18%5
        candidate += 1
        checked += 1
    return {'primes': primes, 'count': len(primes), 'last_checked': candidate}

