def experiment_10437(seed=42, steps=12):
    """Generated micro-experiment 10437: probability clocks; parameters 613, 5, 8, 77."""
    x = (seed + 613) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 5 < 2:
            x = (x * 8 + 77) % 100003
        else:
            x = (x + 613 * 5) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 5
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(10438, 'modular orbits')
@bounded(1, 100)
def experiment_10438(seed=42, steps=12):
    """Generated micro-experiment 10438: modular orbits; parameters 701, 26, 26, 11."""
    cells = [(seed >> (j % 16) ^ (j * 701)) % 2 for j in range(26+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 26%2 else 1)
            else:
                new_cells.append(cells[j] if 11%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

