@experiment(10620, 'modular orbits')
@bounded(1, 100)
def experiment_10620(seed=42, steps=12):
    """Generated micro-experiment 10620: modular orbits; parameters 34, 11, 55, 32."""
    cells = [(seed >> (j % 16) ^ (j * 34)) % 2 for j in range(11+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 55%2 else 1)
            else:
                new_cells.append(cells[j] if 32%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

