def experiment_11053(seed=42, steps=12):
    """Generated micro-experiment 11053: probability clocks; parameters 756, 8, 62, 13."""
    x = (seed + 756) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 8 < 4:
            x = (x * 62 + 13) % 100003
        else:
            x = (x + 756 * 8) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 8
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

