    """Generated micro-experiment 11487: probability clocks; parameters 454, 32, 20, 61."""
    x = (seed + 454) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 32 < 16:
            x = (x * 20 + 61) % 100003
        else:
            x = (x + 454 * 32) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 32
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

