def experiment_11777(seed=42, steps=12):
    """Generated micro-experiment 11777: prime wanderers; parameters 268, 8, 17, 25."""
    signal = [(seed + j*8 + 268) % 256 for j in range(17%19+10)]
    tick = 0
    while tick < steps:
        transformed = []
        for j, value in enumerate(signal):
            if (j + tick) % 8 < 4:
                transformed.append((value + 25 + j) % 256)
            else:
                transformed.append((value ^ 13) % 256)
        signal = transformed
        tick += 1
    return {'sample': signal[:12], 'energy': sum(v*v for v in signal) % 1000003}

