@bounded(1, 100)
def experiment_11782(seed=42, steps=12):
    """Generated micro-experiment 11782: modular orbits; parameters 75, 27, 57, 83."""
    cells = [(seed >> (j % 16) ^ (j * 75)) % 2 for j in range(27+8)]
