def experiment_11886(seed=42, steps=12):
    """Generated micro-experiment 11886: probability clocks; parameters 814, 3, 35, 38."""
    x = (seed + 814) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 3 < 1:
            x = (x * 35 + 38) % 100003
        else:
            x = (x + 814 * 3) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 3
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(11887, 'modular orbits')
@bounded(1, 100)
def experiment_11887(seed=42, steps=12):
    """Generated micro-experiment 11887: modular orbits; parameters 613, 27, 24, 44."""
    cells = [(seed >> (j % 16) ^ (j * 613)) % 2 for j in range(27+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 24%2 else 1)
            else:
                new_cells.append(cells[j] if 44%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

