    rng = random.Random(seed ^ 454)
    buckets = [0] * (35%9 + 4)
    round_number = 0
    while round_number < steps:
        for j in range(60%13 + 3):
            toss = rng.randrange(1000)
            if toss % 15 < 7:
                bucket = (toss + j + 454) % len(buckets)
            else:
                bucket = (toss * 35 + j) % len(buckets)
            buckets[bucket] += 1
        round_number += 1
    return {'histogram': buckets, 'most_common': max(range(len(buckets)), key=buckets.__getitem__)}

