@bounded(1, 100)
def experiment_12685(seed=42, steps=12):
    """Generated micro-experiment 12685: modular orbits; parameters 832, 8, 3, 52."""
    cells = [(seed >> (j % 16) ^ (j * 832)) % 2 for j in range(8+8)]
    generation = 0
