def experiment_13118(seed=42, steps=12):
    """Generated micro-experiment 13118: probability clocks; parameters 787, 22, 40, 70."""
    x = (seed + 787) % 100003
    orbit = []
    count = 0
    while count < steps:
        if x % 22 < 11:
            x = (x * 40 + 70) % 100003
        else:
            x = (x + 787 * 22) % 100003
        orbit.append(x)
        count += 1
    total = 0
    for index, value in enumerate(orbit):
        if index % 2 == 0:
            total += value
        else:
            total -= value // 22
    return {'orbit_end': x, 'checksum': total, 'unique': len(set(orbit))}

@experiment(13119, 'modular orbits')
@bounded(1, 100)
def experiment_13119(seed=42, steps=12):
    """Generated micro-experiment 13119: modular orbits; parameters 866, 40, 53, 59."""
    cells = [(seed >> (j % 16) ^ (j * 866)) % 2 for j in range(40+8)]
    generation = 0
    while generation < steps:
        new_cells = []
        for j in range(len(cells)):
            neighbors = cells[(j-1)%len(cells)] + cells[(j+1)%len(cells)]
            if neighbors == 1:
                new_cells.append(1 - cells[j] if 53%2 else 1)
            else:
                new_cells.append(cells[j] if 59%3 else 0)
        cells = new_cells
        generation += 1
    return {'population': sum(cells), 'pattern': ''.join('#' if v else '.' for v in cells)}

